// PokeMem — 遭遇战场景卡通地形图，全是矢量 SVG（任意尺寸都清晰）
// 7 张是用户发的「地図のアイコン」大图经 vtracer 矢量化：原尺寸裁切 -> 品红底 -> 追踪，
// 再把品红背景层里的“洞”（图标轮廓）当底色形状、删掉品红层，背景透明；
// 大图里没有城市和洞穴，这两个按同风格手绘（粗深色描边 + 扁平 pastel 填色）。
// GitHub 推送传不了二进制文件，所以图以 base64 嵌在这里——和头像 avatars.js、卡背图一个做法。
// 母本在 ~/workspace/pokemem/img/scene-icons/（trace_icons5.py、city.svg、cave.svg）。
// 图标缺失时 encounter-ui.js 回落到 imgUrl(sc.art) 的宝可梦立绘。
var SCENE_ICONS = {
  grassland: "data:image/svg+xml;base64,",
  forest: "data:image/svg+xml;base64,",
  stream: "data:image/svg+xml;base64,",
  city: "data:image/svg+xml;base64,",
  desert: "data:image/svg+xml;base64,",
  cave: "data:image/svg+xml;base64,",
  ocean: "data:image/svg+xml;base64,",
  glacier: "data:image/svg+xml;base64,",
  "champions-road": "data:image/svg+xml;base64,"
};
if (typeof module !== "undefined") module.exports = SCENE_ICONS;
